static void restore_cursor() {
    if (prev_x < 0) return;

    for (int y = 0; y < CURSOR_SIZE; y++) {
        for (int x = 0; x < CURSOR_SIZE; x++) {
            fb_put_pixel(prev_x + x, prev_y + y, backup[y][x]);
        }
    }
}

static void draw_cursor(int x, int y) {
    for (int y0 = 0; y0 < CURSOR_SIZE; y0++) {
        for (int x0 = 0; x0 < CURSOR_SIZE; x0++) {

            int px = x + x0;
            int py = y + y0;

            uint8_t p = cursor[y0][x0];

            if (p == 2)
                fb_put_pixel(px, py, 0x00000000); // black outline
            else if (p == 1)
                fb_put_pixel(px, py, 0x00FFFFFF); // white fill
        }
    }
}

static void save_cursor(int x, int y) {
    for (int y0 = 0; y0 < CURSOR_SIZE; y0++) {
        for (int x0 = 0; x0 < CURSOR_SIZE; x0++) {
            backup[y0][x0] = fb_get_pixel(x + x0, y + y0);
        }
    }
}

void handle_mouse(int x, int y, int left, int right) {
    restore_cursor();
    save_cursor(x, y);
    draw_cursor(x, y);

    // left or right clicks
    if (left) {}
    if (right) {}

    prev_x = x;
    prev_y = y;
}

